PRAGMA foreign_keys = ON;
CREATE TABLE connections (provider TEXT PRIMARY KEY CHECK(provider IN ('github','cloudflare','hostinger')), encrypted_token TEXT NOT NULL, account_label TEXT NOT NULL, provider_account_id TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', created_time TEXT NOT NULL, updated_time TEXT NOT NULL, last_verified_time TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', framework_type TEXT NOT NULL, repository_owner TEXT, repository_name TEXT NOT NULL, repository_id TEXT, production_branch TEXT NOT NULL DEFAULT 'main', cloudflare_account_id TEXT, cloudflare_project_name TEXT, cloudflare_project_id TEXT, build_command TEXT NOT NULL DEFAULT '', root_directory TEXT NOT NULL DEFAULT '', output_directory TEXT NOT NULL DEFAULT '', custom_domain TEXT, zone_id TEXT, project_status TEXT NOT NULL DEFAULT 'draft', private INTEGER NOT NULL DEFAULT 1, last_commit_sha TEXT, last_commit_message TEXT, lock_until INTEGER NOT NULL DEFAULT 0, created_time TEXT NOT NULL, updated_time TEXT NOT NULL);
CREATE TABLE deployments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), provider_deployment_id TEXT UNIQUE, commit_sha TEXT, commit_message TEXT, environment TEXT NOT NULL DEFAULT 'production', status TEXT NOT NULL, preview_url TEXT, production_url TEXT, error_summary TEXT, started_time TEXT NOT NULL, completed_time TEXT, build_command TEXT, branch TEXT);
CREATE INDEX deployments_project_time ON deployments(project_id, started_time DESC);
CREATE TABLE activity_logs (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), action TEXT NOT NULL, status TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}', timestamp TEXT NOT NULL);
CREATE INDEX activity_month ON activity_logs(action, timestamp);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
